/**
 * @ubgo/validator — the TypeScript runtime for schemas generated by
 * github.com/ubgo/validator.
 *
 * What it is (docsi/MISSION.md ADR-VAL-002): a thin shim over Ajv that
 * (1) validates a value against the JSON Schema the Go emitter produced,
 * (2) implements Standard Schema and Standard JSON Schema so it drops into
 * tRPC / TanStack Form / React Hook Form / Hono without adapters, and
 * (3) honors the portability manifest — opaque rules stub and warn, server
 * rules round-trip to the backend, and nothing is silently accepted that
 * the backend would reject (ADR-VAL-004/005).
 *
 * The backend is always authoritative. Everything here is UX courtesy; the
 * Go `Validate()` on submit is the decision.
 */

import type { ErrorObject, Options as AjvOptions, ValidateFunction } from "ajv";
import AjvDraft07Import from "ajv";
import Ajv2020Import from "ajv/dist/2020.js";
import addFormatsImport from "ajv-formats";

import { toIssues, localize, type Issue, type Catalog, X_CODE, X_MESSAGE, CODE_CUSTOM } from "./issues.js";
import {
  jsonPathToSegments,
  segmentsToJSONPath,
  PORTABILITY_CLASSES,
  type Manifest,
  type ManifestEntry,
} from "./manifest.js";
import type { StandardSchemaV1 } from "./standard.js";
import type { FromSchema, JSONSchema } from "json-schema-to-ts";

export type { Issue, Catalog } from "./issues.js";
export { render, toIssues, localize } from "./issues.js";
export type { Manifest, ManifestEntry, ManifestKind, PortabilityClass } from "./manifest.js";
export { jsonPathToSegments, pointerToSegments, segmentsToJSONPath } from "./manifest.js";
export type { StandardSchemaV1 } from "./standard.js";

/** An Ajv instance, whichever dialect class built it. */
type AjvInstance = import("ajv").default;

/** Constructor shape shared by Ajv's dialect classes. */
type AjvCtor = new (opts?: AjvOptions) => AjvInstance;

/**
 * Unwraps a CommonJS module imported from ESM. Ajv and ajv-formats ship
 * CJS; under Node's ESM loader the default import is `module.exports`,
 * under bundlers it may be `{ default }`. This is the one interop boundary
 * in the package, so the cast lives here with its reason.
 */
function interop<T>(mod: unknown): T {
  const m = mod as { default?: T };
  return (m.default ?? mod) as T;
}

const AjvDraft07 = interop<AjvCtor>(AjvDraft07Import);
const Ajv2020 = interop<AjvCtor>(Ajv2020Import);
const addFormats = interop<(ajv: AjvInstance) => AjvInstance>(addFormatsImport);

/** The `$schema` URIs the Go emitter writes. */
export const DRAFT_2020 = "https://json-schema.org/draft/2020-12/schema";
export const DRAFT_07 = "http://json-schema.org/draft-07/schema#";

/** Vendor string reported through Standard Schema. */
export const VENDOR = "ubgo";

/** Default debounce for server round-trips, in milliseconds. */
export const DEFAULT_DEBOUNCE_MS = 300;

/**
 * Wire format of a server rule round-trip. The Go side mounts one handler
 * per registered async rule at the manifest's endpoint (`POST /v/<rule>`)
 * and runs the same closure it runs in `Validate()`.
 */
export interface ServerRequest {
  readonly rule: string;
  readonly value: unknown;
}

/** Response of a server rule round-trip. */
export interface ServerResponse {
  readonly ok: boolean;
  /** Issues when `ok` is false; a bare `{ok:false}` becomes one `custom` issue. */
  readonly issues?: ReadonlyArray<Pick<Issue, "code" | "message"> & Partial<Issue>>;
}

/** A successful validation. */
export interface Success<T> {
  readonly ok: true;
  readonly value: T;
}

/** A failed validation. */
export interface Failure {
  readonly ok: false;
  readonly issues: ReadonlyArray<Issue>;
}

/** The result of a validation run. */
export type Result<T> = Success<T> | Failure;

/** Options for {@link createValidator}. */
export interface Options {
  /**
   * The portability manifest emitted alongside the schema. Without it the
   * runtime cannot know which rules it is missing and treats the schema as
   * fully portable — pass it whenever the schema was generated with one.
   */
  readonly manifest?: Manifest;

  /**
   * Called once per non-portable entry the runtime cannot execute locally
   * (opaque, wasm, cel, lossy). Default: `console.warn` once per entry.
   * Pass a no-op to silence in production after reviewing the manifest.
   */
  readonly onNonPortable?: (entry: ManifestEntry) => void;

  /**
   * Whether server rules round-trip during `validateAsync`. Default true
   * when the manifest has server entries with endpoints.
   */
  readonly serverRules?: boolean;

  /** Base URL prefixed to relative endpoints. Default: none. */
  readonly baseURL?: string;

  /** Debounce window for server round-trips. Default {@link DEFAULT_DEBOUNCE_MS}. */
  readonly debounceMs?: number;

  /** `fetch` implementation; default `globalThis.fetch`. */
  readonly fetch?: typeof globalThis.fetch;

  /** Extra Ajv options merged over the runtime defaults. */
  readonly ajv?: AjvOptions;

  /**
   * Message catalog (the JSON from `validatorctl catalog`, or a
   * translation of it). Messages of every issue — local or from the
   * server — are rendered from it by code.
   */
  readonly catalog?: Catalog;
}

/**
 * A compiled validator. Implements Standard Schema (`~standard`) and
 * Standard JSON Schema (`~standard.jsonSchema`).
 */
export interface Validator<T = unknown> extends StandardSchemaV1<unknown, T> {
  /** The JSON Schema document this validator runs. */
  readonly schema: Readonly<Record<string, unknown>>;

  /** The manifest, empty when none was supplied. */
  readonly manifest: Manifest;

  /** Manifest entries that cannot run in the browser at all. */
  readonly nonPortable: ReadonlyArray<ManifestEntry>;

  /** Manifest entries that round-trip to the server during `validateAsync`. */
  readonly serverEntries: ReadonlyArray<ManifestEntry>;

  /** Synchronous, local-only validation (JSON Schema rules). */
  validate(value: unknown): Result<T>;

  /**
   * Local validation followed, when the local pass succeeds, by every server
   * rule round-trip (debounced per rule). Server issues are merged in.
   */
  validateAsync(value: unknown): Promise<Result<T>>;
}

/**
 * Infers the validated value's type from a schema literal. Feed it the
 * `as const` module `validatorctl ir export --ts` writes; a plain JSON
 * import loses its literal types and infers `unknown`.
 */
export type Infer<S> = S extends JSONSchema ? FromSchema<S> : unknown;

/**
 * Builds a validator from an emitted schema and its manifest.
 *
 * When `schema` is a const literal (the `--ts` export), the value type is
 * inferred from it; otherwise pass it explicitly: `createValidator<User>(…)`.
 */
export function createValidator<const S extends Readonly<Record<string, unknown>>>(
  schema: S,
  options?: Options,
): Validator<Infer<S>>;
export function createValidator<T>(schema: Readonly<Record<string, unknown>>, options?: Options): Validator<T>;
export function createValidator<T = unknown>(
  schema: Readonly<Record<string, unknown>>,
  options: Options = {},
): Validator<T> {
  const manifest = checkManifest(options.manifest);
  const dialect = schema["$schema"];
  // The Go side coerces JSON/form strings for fields marked `coerce`; Ajv
  // can only coerce globally, so the presence of any such entry turns it
  // on for the whole document — the closest faithful mirror, documented in
  // the manifest entry's reason.
  const coerce = manifest.entries.some((e) => e.kind === "transform" && e.name === "coerce");
  const ajv = makeAjv(dialect, { ...(coerce ? { coerceTypes: true } : {}), ...options.ajv });
  const compiled = ajv.compile(schema as object) as ValidateFunction;

  const serverEntries = manifest.entries.filter((e) => e.class === "server" && e.endpoint !== undefined);
  const nonPortable = manifest.entries.filter((e) => !(e.class === "server" && e.endpoint !== undefined));
  const warn = options.onNonPortable ?? defaultWarn;
  for (const e of nonPortable) warn(e);

  const serverRules = options.serverRules ?? serverEntries.length > 0;
  const fetchImpl = options.fetch ?? globalThis.fetch;
  const debounce = new Debouncer(options.debounceMs ?? DEFAULT_DEBOUNCE_MS);

  const catalog = options.catalog;
  const finish = (issues: Issue[]): Issue[] => (catalog ? localize(issues, catalog) : issues);

  const validate = (value: unknown): Result<T> => {
    const ok = compiled(value);
    if (ok) return { ok: true, value: value as T };
    return { ok: false, issues: finish(toIssues(compiled.errors as ErrorObject[] | null)) };
  };

  const validateAsync = async (value: unknown): Promise<Result<T>> => {
    const local = validate(value);
    if (!local.ok || !serverRules || serverEntries.length === 0) return local;
    const issues: Issue[] = [];
    await Promise.all(
      serverEntries.map(async (entry) => {
        const segments = jsonPathToSegments(entry.path);
        const field = valueAt(value, segments);
        const got = await debounce.run(entry.path + "|" + String(entry.ref), () =>
          roundTrip(fetchImpl, options.baseURL, entry, field),
        );
        for (const i of got) {
          // The server validates one field and does not know its path in
          // the document, so an empty path means "this field". Rule and
          // params default to the manifest entry so the issue matches what
          // the Go executors produce for the same failure.
          issues.push({
            code: i.code,
            message: i.message,
            path: i.path ? i.path : entry.path,
            segments: i.segments ?? segments,
            rule: i.rule ? i.rule : entry.name,
            params: { ref: entry.ref, ...(i.params ?? {}) },
          });
        }
      }),
    );
    if (issues.length === 0) return local;
    return { ok: false, issues: finish(issues) };
  };

  const toStandard = (r: Result<T>): StandardSchemaV1.Result<T> =>
    r.ok
      ? { value: r.value }
      : { issues: r.issues.map((i) => ({ message: i.message, path: i.segments })) };

  const jsonSchema: StandardSchemaV1.JSONSchemaProps = {
    input: ({ target }) => requireDialect(schema, dialect, target),
    output: ({ target }) => requireDialect(schema, dialect, target),
  };

  const standard: StandardSchemaV1.Props<unknown, T> = {
    version: 1,
    vendor: VENDOR,
    validate: (value) =>
      serverRules && serverEntries.length > 0
        ? validateAsync(value).then(toStandard)
        : toStandard(validate(value)),
    jsonSchema,
  };

  return {
    "~standard": standard,
    schema,
    manifest,
    nonPortable,
    serverEntries,
    validate,
    validateAsync,
  };
}

/** Warns once per entry, the default `onNonPortable`. */
const warned = new WeakSet<ManifestEntry>();
function defaultWarn(entry: ManifestEntry): void {
  if (warned.has(entry)) return;
  warned.add(entry);
  console.warn(
    `[@ubgo/validator] ${entry.path}: ${entry.kind} "${entry.name}" is ${entry.class} and runs server-side only — ${entry.reason}`,
  );
}

/** Validates a manifest's shape so a mangled file fails loudly at build. */
function checkManifest(m: Manifest | undefined): Manifest {
  if (m === undefined) return { entries: [] };
  if (!Array.isArray(m.entries)) {
    throw new TypeError("@ubgo/validator: manifest.entries must be an array");
  }
  for (const e of m.entries) {
    if (typeof e.path !== "string" || typeof e.name !== "string" || !PORTABILITY_CLASSES.has(e.class)) {
      throw new TypeError(`@ubgo/validator: malformed manifest entry ${JSON.stringify(e)}`);
    }
  }
  return m;
}

/** Picks the Ajv class for the schema's dialect and registers our keywords. */
function makeAjv(dialect: unknown, extra: AjvOptions | undefined): AjvInstance {
  // Strict schema/types/tuples catch emitter bugs (a keyword with no type
  // to apply to). strictRequired stays off, as in Ajv's own default: the
  // if/then idiom the emitter uses for conditions names required
  // properties inside `if` without redeclaring them there.
  // verbose attaches parentSchema to each error, which is where the
  // emitter's x-code / x-message vendor keywords live.
  const base: AjvOptions = {
    allErrors: true,
    verbose: true,
    strictSchema: true,
    strictTypes: true,
    strictTuples: true,
    strictRequired: false,
    ...extra,
  };
  const ajv: AjvInstance = dialect === DRAFT_07 ? new AjvDraft07(base) : new Ajv2020(base);
  if (dialect !== DRAFT_07 && dialect !== DRAFT_2020 && dialect !== undefined) {
    throw new TypeError(`@ubgo/validator: unsupported $schema ${String(dialect)}`);
  }
  addFormats(ajv);
  // The Go emitter's vendor keywords carry error metadata; declaring them
  // keeps Ajv strict mode on for everything else.
  ajv.addKeyword({ keyword: X_CODE, schemaType: "string" });
  ajv.addKeyword({ keyword: X_MESSAGE, schemaType: "string" });
  return ajv;
}

/** Standard JSON Schema: hand back the document when the dialect matches. */
function requireDialect(
  schema: Readonly<Record<string, unknown>>,
  dialect: unknown,
  target: StandardSchemaV1.JSONSchemaTarget,
): Record<string, unknown> {
  const have = dialect === DRAFT_07 ? "draft-07" : "draft-2020-12";
  const want = target === "openapi-3.0" ? "draft-07" : target;
  if (have !== want) {
    throw new Error(
      `@ubgo/validator: schema is ${have} but ${target} was requested; regenerate with validatorctl ir export --draft ${want === "draft-07" ? "07" : "2020"}`,
    );
  }
  return { ...schema };
}

/** Reads a nested value by path segments; `*` wildcards yield undefined. */
export function valueAt(value: unknown, segments: ReadonlyArray<PropertyKey>): unknown {
  let cur: unknown = value;
  for (const seg of segments) {
    if (cur === null || typeof cur !== "object" || seg === "*") return undefined;
    cur = (cur as Record<PropertyKey, unknown>)[seg];
  }
  return cur;
}

/** Performs one server round-trip and normalizes the response to issues. */
async function roundTrip(
  fetchImpl: typeof globalThis.fetch | undefined,
  baseURL: string | undefined,
  entry: ManifestEntry,
  value: unknown,
): Promise<ReadonlyArray<Partial<Issue> & Pick<Issue, "code" | "message">>> {
  if (fetchImpl === undefined) {
    throw new Error("@ubgo/validator: no fetch available for server rules; pass options.fetch");
  }
  const url = (baseURL ?? "") + String(entry.endpoint);
  const body: ServerRequest = { rule: String(entry.ref), value };
  const res = await fetchImpl(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    throw new Error(`@ubgo/validator: ${url} responded ${res.status}`);
  }
  const data = (await res.json()) as ServerResponse;
  if (data.ok) return [];
  if (data.issues && data.issues.length > 0) return data.issues;
  return [{ code: CODE_CUSTOM, message: `rule ${String(entry.ref)} rejected the value` }];
}

/**
 * Trailing-edge debouncer keyed by string: rapid calls for the same key
 * collapse into one execution of the LAST call, and every caller receives
 * that result. Keeps typing in a form from firing a request per keystroke.
 */
class Debouncer {
  private readonly pending = new Map<
    string,
    { timer: ReturnType<typeof setTimeout>; fn: () => Promise<unknown>; waiters: Array<{ resolve: (v: unknown) => void; reject: (e: unknown) => void }> }
  >();

  constructor(private readonly ms: number) {}

  run<R>(key: string, fn: () => Promise<R>): Promise<R> {
    return new Promise<R>((resolve, reject) => {
      const existing = this.pending.get(key);
      if (existing) clearTimeout(existing.timer);
      const waiters = existing?.waiters ?? [];
      waiters.push({ resolve: resolve as (v: unknown) => void, reject });
      const timer = setTimeout(() => {
        const slot = this.pending.get(key);
        this.pending.delete(key);
        if (!slot) return;
        slot
          .fn()
          .then((v) => slot.waiters.forEach((w) => w.resolve(v)))
          .catch((e: unknown) => slot.waiters.forEach((w) => w.reject(e)));
      }, this.ms);
      this.pending.set(key, { timer, fn, waiters });
    });
  }
}

/** Formats path segments for messages; re-exported for adapters. */
export { segmentsToJSONPath as formatPath };
